package com.nivor.focus;import jakarta.validation.constraints.*;import java.time.LocalDateTime;
public final class FocusDtos{private FocusDtos(){}public record StartRequest(@Min(60)@Max(14400)int durationSeconds,Long taskId){}public record SessionView(Long id,Long taskId,String taskTitle,int durationSeconds,int elapsedSeconds,LocalDateTime startedAt,LocalDateTime pausedAt,LocalDateTime endedAt,FocusStatus status){static SessionView from(FocusSession x){return new SessionView(x.getId(),x.getTask()==null?null:x.getTask().getId(),x.getTask()==null?null:x.getTask().getTitle(),x.getDurationSeconds(),x.getElapsedSeconds(),x.getStartedAt(),x.getPausedAt(),x.getEndedAt(),x.getStatus());}}public record Summary(long completedSessions,long focusSeconds,long focusMinutes){}}
